/**
 * Protocol-artifact sidecars are bound to what the JWS signed: (type, algorithm, hash), digest computed with the DECLARED
 * algorithm, no duplicates, no orphan sidecars, hmac never "passes".
 *
 * Vectors: test-vectors/v11-hardening/H001..H007 (generated by
 * scripts/generate-hardening-vectors.ts).
 */
import { describe, it, expect } from "vitest";
import { readFileSync, readdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { verifyReceiptEnvelope } from "../verify-1.1.js";
import type { VerifyOptions } from "../verify-1.1.js";
import type { SignedJwksHistory } from "../types-1.1.js";
import type { PublicJwk } from "../verifier.js";

const DIR = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "..",
  "test-vectors",
  "v11-hardening"
);

interface Vec {
  vector_id: string;
  envelope: Record<string, unknown>;
  verify_options: {
    currentTime: number;
    trust_anchor_sha256: string;
    jwks: { keys: PublicJwk[] };
  };
  expected: { outcome: string; errorCode: string | null };
}

const load = (n: string): Vec =>
  JSON.parse(readFileSync(join(DIR, n), "utf8")) as Vec;

function history(v: Vec): SignedJwksHistory {
  const t = v.verify_options.currentTime;
  const payload = {
    schema_version: "1.0",
    entries: v.verify_options.jwks.keys.map((k) => ({
      kid: (k as { kid?: string }).kid ?? "",
      jwk_pub: k as unknown as Record<string, unknown>,
      valid_from: t - 86_400,
      valid_to: null,
    })),
    history_chain_sha256: "0".repeat(64),
  };
  const h = Buffer.from(JSON.stringify({ alg: "EdDSA" })).toString("base64url");
  const b = Buffer.from(JSON.stringify(payload)).toString("base64url");
  return { jws_compact: `${h}.${b}.AA`, signed_by_root_sha256: "0".repeat(64) };
}

function opts(v: Vec, mode: "strict" | "compat"): VerifyOptions {
  return {
    jwksHistory: history(v),
    trustAnchorPemSha256: v.verify_options.trust_anchor_sha256,
    policyOidAllowlist: ["1.2.3.4.5.6.7.8.9"],
    allowStagingRoots: true,
    currentTimeSeconds: v.verify_options.currentTime,
    expectedSubject: "buyer_agent",
    mode,
  };
}

const FILES = readdirSync(DIR)
  .filter((f) => f.startsWith("H00"))
  .sort();

describe("sidecars bound to signed artifacts", () => {
  it("loads exactly the 7 hardening vectors", () => {
    expect(FILES.length).toBe(7);
  });

  for (const mode of ["strict", "compat"] as const) {
    it.each(FILES)(`%s — ${mode} matches expected`, async (name) => {
      const v = load(name);
      const r = await verifyReceiptEnvelope(
        v.envelope as unknown as Parameters<typeof verifyReceiptEnvelope>[0],
        opts(v, mode)
      );
      expect(r.errorCode ?? null).toBe(v.expected.errorCode);
      expect(r.outcome).toBe(v.expected.outcome);
    });
  }
});
